// Adds an XCUITest target (HopReadyUITests) to the generated iOS project, so end-to-end tests run
// with Apple's own tooling: `xcodebuild test -only-testing:HopReadyUITests`. The project in ios/ is
// regenerated by `expo prebuild`, so the target has to be recreated by this plugin each time.
const fs = require('node:fs');
const path = require('node:path');
const { withDangerousMod, withFinalizedMod, withXcodeProject } = require('expo/config-plugins');

const TARGET_NAME = 'HopReadyUITests';
const SOURCE_DIR = path.join(__dirname, '..', 'e2e', 'ios');
const UI_TESTING_PRODUCT_TYPE = '"com.apple.product-type.bundle.ui-testing"';

function swiftSources() {
  if (!fs.existsSync(SOURCE_DIR)) return [];
  return fs
    .readdirSync(SOURCE_DIR)
    .filter((file) => file.endsWith('.swift'))
    .sort();
}

function copyTestSources(config) {
  return withDangerousMod(config, [
    'ios',
    async (modConfig) => {
      const destination = path.join(modConfig.modRequest.platformProjectRoot, TARGET_NAME);
      fs.mkdirSync(destination, { recursive: true });
      for (const file of swiftSources()) {
        fs.copyFileSync(path.join(SOURCE_DIR, file), path.join(destination, file));
      }
      return modConfig;
    },
  ]);
}

// The library writes names quoted when it creates them and reads them back unquoted.
function findByName(find, name) {
  return find(name) ?? find(`"${name}"`) ?? null;
}

// A project generated without --clean keeps the target from last time, so test files added since
// then are put into its Sources phase here.
function addMissingSources(project) {
  const targetKey = findByName((name) => project.findTargetKey(name), TARGET_NAME);
  const groupKey = findByName((name) => project.findPBXGroupKey({ name }), TARGET_NAME);
  if (!targetKey || !groupKey) {
    throw new Error(`with-ios-ui-tests: ${TARGET_NAME} exists but its target or group is missing`);
  }
  const phase = project.pbxSourcesBuildPhaseObj(targetKey);
  const present = new Set(
    (phase?.files ?? []).map((entry) => String(entry.comment).replace(/ in Sources$/, '')),
  );
  for (const file of swiftSources()) {
    if (!present.has(file)) project.addSourceFile(file, { target: targetKey }, groupKey);
  }
}

function addTestTarget(config) {
  return withXcodeProject(config, (modConfig) => {
    const project = modConfig.modResults;
    if (project.pbxTargetByName(TARGET_NAME)) {
      addMissingSources(project);
      return modConfig;
    }

    const appTarget = project.getFirstTarget();
    const appName = appTarget.firstTarget.name.replace(/"/g, '');
    const bundleId = modConfig.ios?.bundleIdentifier ?? 'au.hopready.HopReady';
    const testTarget = project.addTarget(
      TARGET_NAME,
      'unit_test_bundle',
      TARGET_NAME,
      `${bundleId}.UITests`,
    );
    // The library only knows unit test bundles; XCUITest needs the UI testing product type.
    project.pbxNativeTargetSection()[testTarget.uuid].productType = UI_TESTING_PRODUCT_TYPE;

    const sources = swiftSources();
    const group = project.addPbxGroup(sources, TARGET_NAME, TARGET_NAME);
    const mainGroup = project.getFirstProject().firstProject.mainGroup;
    project.addToPbxGroup(group.uuid, mainGroup);
    project.addBuildPhase(sources, 'PBXSourcesBuildPhase', 'Sources', testTarget.uuid);
    project.addBuildPhase([], 'PBXFrameworksBuildPhase', 'Frameworks', testTarget.uuid);
    project.addTargetDependency(testTarget.uuid, [appTarget.uuid]);

    const configurationList =
      project.pbxNativeTargetSection()[testTarget.uuid].buildConfigurationList;
    const configurations = project.pbxXCConfigurationList()[configurationList].buildConfigurations;
    const buildConfigurations = project.pbxXCBuildConfigurationSection();
    for (const { value } of configurations) {
      const settings = buildConfigurations[value].buildSettings;
      delete settings.INFOPLIST_FILE;
      Object.assign(settings, {
        GENERATE_INFOPLIST_FILE: 'YES',
        TEST_TARGET_NAME: `"${appName}"`,
        SWIFT_VERSION: '5.0',
        IPHONEOS_DEPLOYMENT_TARGET: '16.4',
        SDKROOT: 'iphoneos',
        TARGETED_DEVICE_FAMILY: '1',
        CODE_SIGN_STYLE: 'Automatic',
        ...(modConfig.ios?.appleTeamId ? { DEVELOPMENT_TEAM: modConfig.ios.appleTeamId } : {}),
      });
    }
    return modConfig;
  });
}

// The library names a test bundle's product like a Spotlight importer and adds an unused copy
// entry for it. Xcode expects a ".xctest" product, so the written project is corrected here.
function correctTestProduct(pbxproj) {
  return pbxproj
    .split('\n')
    .filter((line) => !line.includes(`${TARGET_NAME}.mdimporter in Copy Files`))
    .join('\n')
    .replaceAll(`${TARGET_NAME}.mdimporter`, `${TARGET_NAME}.xctest`)
    .replace(
      new RegExp(
        `(/\\* ${TARGET_NAME}\\.xctest \\*/ = \\{isa = PBXFileReference;[^\\n]*?)fileEncoding = undefined; lastKnownFileType = undefined; `,
      ),
      '$1',
    );
}

// The shared scheme lists what `xcodebuild test` runs; the new target is added as a testable.
function addTargetToScheme(config) {
  return withFinalizedMod(config, [
    'ios',
    async (modConfig) => {
      const iosRoot = modConfig.modRequest.platformProjectRoot;
      const projectDir = fs.readdirSync(iosRoot).find((entry) => entry.endsWith('.xcodeproj'));
      if (!projectDir) throw new Error('with-ios-ui-tests: no .xcodeproj found in ios/');
      const pbxprojPath = path.join(iosRoot, projectDir, 'project.pbxproj');
      const pbxproj = correctTestProduct(fs.readFileSync(pbxprojPath, 'utf8'));
      if (pbxproj.includes(`${TARGET_NAME}.mdimporter`)) {
        throw new Error('with-ios-ui-tests: the test product could not be renamed to .xctest');
      }
      fs.writeFileSync(pbxprojPath, pbxproj);
      const targetMatch = pbxproj.match(
        new RegExp(`([0-9A-F]{24}) /\\* "?${TARGET_NAME}"? \\*/ = \\{\\s*isa = PBXNativeTarget;`),
      );
      if (!targetMatch) throw new Error(`with-ios-ui-tests: ${TARGET_NAME} target not found`);
      const schemeDir = path.join(iosRoot, projectDir, 'xcshareddata', 'xcschemes');
      const schemeFile = fs.readdirSync(schemeDir).find((entry) => entry.endsWith('.xcscheme'));
      if (!schemeFile) throw new Error('with-ios-ui-tests: no shared scheme found');
      const schemePath = path.join(schemeDir, schemeFile);
      const scheme = fs.readFileSync(schemePath, 'utf8');
      if (scheme.includes(`BlueprintName = "${TARGET_NAME}"`)) return modConfig;

      const testable = `
         <TestableReference
            skipped = "NO">
            <BuildableReference
               BuildableIdentifier = "primary"
               BlueprintIdentifier = "${targetMatch[1]}"
               BuildableName = "${TARGET_NAME}.xctest"
               BlueprintName = "${TARGET_NAME}"
               ReferencedContainer = "container:${projectDir}">
            </BuildableReference>
         </TestableReference>`;
      const withTestables = scheme.includes('<Testables>')
        ? scheme.replace('<Testables>', `<Testables>${testable}`)
        : scheme.replace(
            /(<TestAction[^>]*>)/,
            `$1\n      <Testables>${testable}\n      </Testables>`,
          );
      if (withTestables === scheme) throw new Error('with-ios-ui-tests: TestAction not found');
      fs.writeFileSync(schemePath, withTestables);
      return modConfig;
    },
  ]);
}

module.exports = function withIosUiTests(config) {
  return addTargetToScheme(addTestTarget(copyTestSources(config)));
};
